import React, { useState } from 'react';
import '../styles/FAQ.css';

const faqData = [
  {
    pregunta: "¿Qué tipo de empresas pueden beneficiarse de sus servicios contables?",
    respuesta: "Atendemos a una amplia gama de clientes, desde emprendedores y freelancers hasta pequeñas y medianas empresas (PYMES) de diversos sectores. Nuestras soluciones se personalizan para adaptarse a las necesidades específicas de cada negocio."
  },
  {
    pregunta: "¿Cómo funciona el servicio de asesoría tributaria?",
    respuesta: "Realizamos un diagnóstico completo de tu situación fiscal, identificamos oportunidades de optimización y te guiamos para garantizar el cumplimiento de todas las normativas. El objetivo es reducir tu carga tributaria de manera legal y eficiente."
  },
  {
    pregunta: "Recibí un comparendo, ¿realmente pueden ayudarme a apelar?",
    respuesta: "Sí. Nuestro equipo jurídico especializado en tránsito analiza tu caso, verifica la validez del procedimiento y prepara una defensa técnica y legal sólida para la audiencia de apelación, aumentando significativamente tus probabilidades de éxito."
  },
  {
    pregunta: "¿Qué necesito para empezar a trabajar con ustedes?",
    respuesta: "El primer paso es agendar una consulta inicial gratuita. En esta reunión, conversaremos sobre tus necesidades y te explicaremos cómo podemos ayudarte. A partir de ahí, te indicaremos la documentación necesaria para comenzar."
  }
];

const FAQItem = ({ faq, index, toggleFAQ, isOpen }) => {
  return (
    <div className={`faq-item ${isOpen ? 'open' : ''}`} onClick={() => toggleFAQ(index)}>
      <div className="faq-pregunta">
        {faq.pregunta}
        <span className="faq-icono">{isOpen ? '-' : '+'}</span>
      </div>
      <div className="faq-respuesta">
        <p>{faq.respuesta}</p>
      </div>
    </div>
  );
};

const FAQ = () => {
  const [openIndex, setOpenIndex] = useState(null);

  const toggleFAQ = index => {
    setOpenIndex(openIndex === index ? null : index);
  };

  return (
    <section className="faq-section">
      <h2 className="faq-titulo">Preguntas Frecuentes</h2>
      <div className="faq-container">
        {faqData.map((faq, index) => (
          <FAQItem key={index} faq={faq} index={index} toggleFAQ={toggleFAQ} isOpen={openIndex === index} />
        ))}
      </div>
    </section>
  );
};

export default FAQ;
